    Simple simple() {
        Expr left = expression();
        if (Lexer.ASSIGNMENT.contains(peek().text)) {
            Lexer.Token operator = tokens.get(cursor++);
            return new Simple(left, operator, expression());
        }
        return new Simple(left, null, null);
