            return unary();
        Expr left = binary(precedence + 1);
        while (PRECEDENCE.getOrDefault(peek().text, 0) == precedence) {
            Lexer.Token operator = tokens.get(cursor++);
            left = new Binary(left, operator, binary(precedence + 1), precedence);
