        while (true) {
            if (at("("))
                target = new Call(target, list("(", ")", this::expression, ListKind.ARGUMENTS));
            else if (at("[")) {
                Lexer.Token left = take("[");
                Expr index = expression();
                target = new Index(target, left, index, take("]"));
            } else if (at("."))
                target = new Member(target, take("."), identifier());
            else
