        }
    }
    Expr primary() {
        Lexer.Token token = peek();
        if (Set.of("identifier", "number", "string").contains(token.kind) ||
            Set.of("true", "false").contains(token.text)) {
            cursor++;
            return new Primary(token);
        }
        if (at("(")) {
            Lexer.Token left = take("(");
            Expr inner = expression();
            return new Paren(left, inner, take(")"));
        }
        fail("expression");
        throw new IllegalStateException();
    }
}

import java.util.*;
final class Printer {
    record Command(int indent, boolean flat, Doc doc) {}
    static void push(List<Command> stack, int indent, boolean flat, List<Doc> documents) {
        for (int index = documents.size() - 1; index >= 0; index--)
            stack.add(new Command(indent, flat, documents.get(index)));
    }
    static boolean fits(int remaining, Command candidate, List<Command> rest) {
        if (remaining < 0)
            return false;
        List<Command> check = new ArrayList<>();
        check.add(candidate);
        int existing = rest.size() - 1;
        while (true) {
            if (check.isEmpty()) {
                if (existing < 0)
                    return true;
                check.add(rest.get(existing--));
            }
            Command command = check.removeLast();
            int indent = command.indent();
            boolean flat = command.flat();
            Doc doc = command.doc();
            if (doc instanceof DocBuilder.Text text)
                remaining -= text.value().length();
            else if (doc instanceof DocBuilder.IfBreak conditional)
                remaining -= (flat ? conditional.flat() : conditional.broken()).length();
            else if (doc == DocBuilder.Break.LINE) {
                if (!flat)
                    return true;
                remaining--;
            } else if (doc == DocBuilder.Break.SOFTLINE) {
                if (!flat)
                    return true;
            } else if (doc == DocBuilder.Break.HARDLINE)
                return true;
            else if (doc instanceof DocBuilder.Concat concat)
                push(check, indent, flat, concat.items());
            else if (doc instanceof DocBuilder.Group group)
                check.add(new Command(indent, group.forced ? false : flat, group.child));
            else if (doc instanceof DocBuilder.Nest nest)
                check.add(new Command(indent, flat, nest.child()));
            else if (doc instanceof DocBuilder.Align align)
                check.add(new Command(indent, flat, align.child()));
            if (remaining < 0)
                return false;
        }
    }
    static void finalizeLine(List<String> result, StringBuilder current, List<String> pending,
                             int width, int column) {
        String output = Lexer.trim(current.toString());
        if (!pending.isEmpty()) {
            String comments = String.join(" ", pending);
            if (column > 0 && output.length() < column - 1 &&
                column - 1 + comments.length() <= width)
                output += " ".repeat(column - 1 - output.length()) + comments;
            else
                output += " " + comments;
            pending.clear();
        }
        result.add(output);
    }
    static List<String> layout(Doc document, int width, int column) {
        List<String> result = new ArrayList<>(), pending = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        List<Command> stack = new ArrayList<>();
        stack.add(new Command(0, false, document));
        while (!stack.isEmpty()) {
            Command command = stack.removeLast();
            int indent = command.indent();
            boolean flat = command.flat();
            Doc doc = command.doc();
            if (doc instanceof DocBuilder.Text text)
                current.append(text.value());
            else if (doc instanceof DocBuilder.IfBreak conditional)
                current.append(flat ? conditional.flat() : conditional.broken());
            else if (doc == DocBuilder.Break.HARDLINE || doc == DocBuilder.Break.LINE && !flat ||
                     doc == DocBuilder.Break.SOFTLINE && !flat) {
                finalizeLine(result, current, pending, width, column);
                current.setLength(0);
                current.append(" ".repeat(indent));
            } else if (doc == DocBuilder.Break.LINE)
                current.append(' ');
            else if (doc instanceof DocBuilder.Concat concat)
                push(stack, indent, flat, concat.items());
            else if (doc instanceof DocBuilder.Nest nest)
                stack.add(new Command(indent + nest.amount(), flat, nest.child()));
            else if (doc instanceof DocBuilder.Align align)
                stack.add(new Command(current.length(), flat, align.child()));
            else if (doc instanceof DocBuilder.Suffix suffix)
                pending.add(suffix.value());
            else if (doc instanceof DocBuilder.Group group) {
                String mode =
                    flat           ? "flat"
                    : group.forced ? "forced"
                    : fits(width - current.length(), new Command(indent, true, group.child), stack)
                        ? "flat"
                        : "break";
                group.mode = mode;
                stack.add(new Command(indent, mode.equals("flat"), group.child));
            }
        }
        finalizeLine(result, current, pending, width, column);
        return result;
    }
}

import java.util.*;
final class Report {
    static void tree(Doc doc, int depth, List<String> lines) {
        String prefix = "  ".repeat(depth);
        switch (doc) {
        case DocBuilder.Text text -> lines.add(prefix + "text \"" + text.value() + "\"");
        case DocBuilder.Suffix suffix -> lines.add(prefix + "suffix \"" + suffix.value() + "\"");
        case DocBuilder.IfBreak conditional ->
            lines.add(prefix + "if_break \"" + conditional.broken() + "\" \"" + conditional.flat() +
                      "\"");
        case DocBuilder.Concat concat -> {
            for (Doc child : concat.items())
                tree(child, depth, lines);
        }
        case DocBuilder.Group group -> {
            lines.add(prefix + "group " + group.mode);
            tree(group.child, depth + 1, lines);
        }
        case DocBuilder.Nest nest -> {
            lines.add(prefix + "nest " + nest.amount());
            tree(nest.child(), depth + 1, lines);
        }
        case DocBuilder.Align align -> {
            lines.add(prefix + "align");
            tree(align.child(), depth + 1, lines);
        }
        case DocBuilder.Break marker -> lines.add(prefix + marker.name().toLowerCase(Locale.ROOT));
        }
    }
    static List<String> tree(Doc doc) {
        List<String> lines = new ArrayList<>();
        tree(doc, 0, lines);
        return lines;
    }
    static final class Hunk {
        int oldStart, newStart, deletes, inserts;
        List<String> lines = new ArrayList<>();
        Hunk(int oldStart, int newStart) {
            this.oldStart = oldStart;
            this.newStart = newStart;
        }
    }
    static List<String> diff(List<String> original, List<String> formatted) {
        int n = original.size(), m = formatted.size();
        int[][] table = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--)
            for (int j = m - 1; j >= 0; j--)
                table[i][j] = original.get(i).equals(formatted.get(j))
                                  ? table[i + 1][j + 1] + 1
                                  : Math.max(table[i + 1][j], table[i][j + 1]);
        int i = 0, j = 0, deleted = 0, inserted = 0;
        List<Hunk> hunks = new ArrayList<>();
        Hunk current = null;
        while (i < n || j < m) {
            if (i < n && j < m && original.get(i).equals(formatted.get(j))) {
                if (current != null) {
                    hunks.add(current);
                    current = null;
                }
                i++;
                j++;
                continue;
            }
            if (current == null)
                current = new Hunk(i, j);
            if (j == m || i < n && table[i + 1][j] >= table[i][j + 1]) {
                current.deletes++;
                deleted++;
                current.lines.add("-" + original.get(i++));
            } else {
                current.inserts++;
                inserted++;
                current.lines.add("+" + formatted.get(j++));
            }
        }
        if (current != null)
            hunks.add(current);
        List<String> result = new ArrayList<>();
        result.add("hunks=" + hunks.size() + " deleted=" + deleted + " inserted=" + inserted);
        for (Hunk hunk : hunks) {
            result.add("@@ -" + (hunk.oldStart + (hunk.deletes > 0 ? 1 : 0)) + "," + hunk.deletes +
                       " +" + (hunk.newStart + (hunk.inserts > 0 ? 1 : 0)) + "," + hunk.inserts +
                       " @@");
            result.addAll(hunk.lines);
        }
        return result;
    }
}
